SELECT *, ROW_NUMBER() OVER (ORDER BY shipping_fee, id) seq_no, AVG(discount) OVER (ORDER BY discount, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) discount_avg_5, NTILE(3) OVER (PARTITION BY store_id ORDER BY amount DESC, id) amount_bucket, SUM(discount) OVER (ORDER BY discount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_discount, DENSE_RANK() OVER (ORDER BY amount DESC NULLS FIRST) amount_dense_rank FROM orders;
